#include <stdlib.h>

int main(void) {
    int N, M, C;
    if (scanf("%d %d %d", &N, &M, &C) != 3) return 0;

    int *next = (int *)calloc(M + 1, sizeof(int));
    int *visited = (int *)calloc(M + 1, sizeof(int));

    for (int i = 0; i < N; i++) {
        int A, D;
        scanf("%d %d", &A, &D);
        if (next[D] == 0) {
            next[D] = A;
        }
    }

    int current = C;
    int swaps = 0;

    while (1) {
        if (next[current] == 0) {
            printf("%d\n", swaps);
            break;
        }

        if (visited[current]) {
            printf("-1\n");
            break;
        }

        visited[current] = 1;
